/* Tactical v2: AP, perception, fog, targeting and held casts. Simulation only. */
(function(g){'use strict';
const C=g.DecideCombatRules||(typeof require==='function'?require('./combat-data.js'):null),D=g.EverTaleBattleData||(typeof require==='function'?require('./battle-data.js'):null),N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null);
const old={...C},copy=x=>JSON.parse(JSON.stringify(x)),live=e=>e.units.filter(u=>u.hp>0),index=u=>D.index(u.n);
for(const w of Object.values(N.weapons))w.targeting={min:1,max:w.range,mode:'single',count:1,heights:w.range>1?[-2,-1,0,1,2]:[-1,0,1],side:'enemy'};
for(const a of Object.values(N.skills)){a.castPoints=a.magic?(a.cost>=9?3:a.cost>=6?2:1):0;a.targeting={min:0,max:a.range,mode:'single',count:1,heights:a.magic?[-2,-1,0,1,2]:[-1,0,1],side:['heal','cure','barrier','aid','antidote','protect'].includes(a.id)?'ally':'enemy'};}
N.skills.fire.targeting.side='both';
const silent=N.uniques.find(u=>u.id==='silent');if(silent){silent.name='Uncast Magic';silent.description='ข้ามแต้มร่าย เวทออกทันที ใช้ 1 AP และ MP ตามเวท';}
function init(e){if(e.systems===2)return;e.systems=2;e.detectSeed=(e.seed||1234567)>>>0;e.detectChecks={};e.discovered=[];e.profiles={};for(const u of e.units){u.action=u.side==='player'?Math.min(2,u.action*2):1;u.sightRange=u.side==='player'?(u.race==='elf'?9:8):5;u.hearingRange=1;u.altitude=0;u.moving=false;u.detected=[];delete u.scanActive;delete u.scanSeen;delete u.scanRound;}perceive(e);}
function level(e,u){return e.scene.cells[index(u)].height+(u.n%2?1:0)+(u.altitude||0);}
function coords(e,a,b){const ai=index(a),bi=index(b);return [bi%e.scene.w-ai%e.scene.w,Math.floor(bi/e.scene.w)-Math.floor(ai/e.scene.w)];}
function los(e,a,b){const [dx,dy]=coords(e,a,b),i=index(a),steps=Math.max(Math.abs(dx),Math.abs(dy));for(let k=1;k<steps;k++){const t=k/steps,c=e.scene.cells[Math.round(Math.floor(i/e.scene.w)+dy*t)*e.scene.w+Math.round(i%e.scene.w+dx*t)];if(!c||c.object==='wall'||c.object==='tree'||c.height>level(e,a)+(level(e,b)-level(e,a))*t+1)return false;}return true;}
function inSight(e,a,b,moving=a.moving){const [dx,dy]=coords(e,a,b),f=a.facing||0,forward=[dx,dy,-dx,-dy][f],lateral=f%2?dx:dy,r=a.sightRange||5;return a.hp>0&&Math.max(Math.abs(dx),Math.abs(dy))<=r&&(!moving||forward>=1&&forward<=r&&Math.abs(lateral)<forward)&&los(e,a,b)&&!(e.design===1&&g.DecideCharacterCombat?.smokeBlocks(e,a,b));}
function conceal(e,u){const i=index(u);if(u.n%2)return 30;return e.scene.cells.some((c,j)=>c.object==='tree'&&Math.abs(j%e.scene.w-i%e.scene.w)+Math.abs(Math.floor(j/e.scene.w)-Math.floor(i/e.scene.w))<=1)?50:80;}
const ranks={D:1,C:2,B:3,A:4,S:5};
function chance(e,a,b,hearing=false){const [dx,dy]=coords(e,a,b),d=Math.max(Math.abs(dx),Math.abs(dy));return Math.max(5,Math.min(95,(hearing?(los(e,a,b)?45:20):conceal(e,b))-Math.max(0,d-1)*5+(ranks[a.grades?.perception]||0)*5-(ranks[b.grades?.stealth]||0)*5-(b.race==='cat'?10:0)));}
function roll(e){e.detectSeed=(Math.imul(e.detectSeed,1664525)+1013904223)>>>0;return e.detectSeed%100+1;}
function note(e,t){e.log.unshift(t);e.log=e.log.slice(0,30);}
function perceive(e,noiseUnit=null){if(e.systems!==2)return;for(const u of e.units)if(u.casting&&(u.hp<=0||u.effects?.stun||u.effects?.silence)){delete u.casting;note(e,u.name+' ถูกขัดจังหวะการร่าย');}if(!noiseUnit)noiseUnit=live(e).find(u=>u.moving)||null;for(const a of live(e)){a.detected=a.detected||[];for(const b of live(e).filter(b=>b.side!==a.side)){const visual=inSight(e,a,b,a.moving),[dx,dy]=coords(e,a,b),hearing=noiseUnit===b&&Math.max(Math.abs(dx),Math.abs(dy))<=(a.hearingRange||1);if(!visual&&!hearing)continue;const kind=visual?'sight':'sound',key=e.round+':'+(e.detectPhase||'player')+':'+a.id+':'+b.id+':'+kind;if(e.detectChecks[key])continue;const pct=chance(e,a,b,!visual),die=roll(e);e.detectChecks[key]={pct,die};note(e,a.name+' ตรวจ '+(visual?'สายตา':'เสียง')+' '+b.name+' '+pct+'% • d100='+die+' → '+(die<=pct?'สำเร็จ':'ไม่พบ'));if(die>pct)continue;if(visual){a.detected=[...new Set([...a.detected,b.id])];if(a.side==='enemy'){a.aware=[...new Set([...(a.aware||[]),b.id])];a.lastSeen=b.n;for(const ally of live(e).filter(x=>x.side==='enemy'&&old.distance(e.scene,x.n,a.n)<=6)){ally.aware=[...new Set([...(ally.aware||[]),b.id])];ally.lastSeen=b.n;}}}else{a.suspicion=index(b);if(a.side==='enemy'){a.lastSeen=b.n;a.facing=Math.abs(dx)>Math.abs(dy)?(dx>0?0:2):(dy>0?1:3);}}}}
const f=fog(e);e.discovered=[...new Set([...(e.discovered||[]),...f.visible])];}
function fog(e){const visible=new Set();if(live(e).some(u=>u.side==='player'&&u.far===e.round))return {visible:e.scene.cells.map((_,i)=>i),explored:e.discovered||[]};for(const p of live(e).filter(u=>u.side==='player')){const r=p.sightRange||8,i=index(p),x=i%e.scene.w,y=Math.floor(i/e.scene.w);for(let yy=Math.max(0,y-r);yy<=Math.min(e.scene.h-1,y+r);yy++)for(let xx=Math.max(0,x-r);xx<=Math.min(e.scene.w-1,x+r);xx++){const j=yy*e.scene.w+xx;if(j===i||inSight(e,p,{n:D.node(j),hp:1},p.moving))visible.add(j);}}return {visible:[...visible],explored:e.discovered||[]};}
function profile(e,key,base){return e.profiles?.[key]||base;}
function checkProfile(p){if(!p||!Number.isInteger(p.min)||!Number.isInteger(p.max)||p.min<0||p.max<p.min||p.max>100||!['single','select','all'].includes(p.mode)||!Number.isInteger(p.count)||p.count<1||p.count>13||!['enemy','ally','both'].includes(p.side)||!Array.isArray(p.heights)||!p.heights.length||p.heights.some(h=>!Number.isInteger(h)||h< -2||h>2))throw Error('กติกาเป้าหมายไม่ถูกต้อง');return p;}
function reachable(e,a,b,p){const d=old.distance(e.scene,a.n,b.n);return b.hp>0&&(b!==a||p.side!=='enemy')&&d>=p.min&&d<=p.max&&p.heights.includes(level(e,b)-level(e,a))&&los(e,a,b)&&(p.side==='both'||(p.side==='ally')===(a.side===b.side));}
function targets(e,p,ids,rule){checkProfile(rule);const available=live(e).filter(b=>reachable(e,p,b,rule)&&(b.side===p.side||C.visible(e,b)));if(rule.mode==='all')return available;const requested=Array.isArray(ids)?ids:[ids];if(!requested.length||new Set(requested).size!==requested.length||requested.length>(rule.mode==='single'?1:rule.count))throw Error('จำนวนเป้าหมายไม่ถูกต้อง');const result=requested.map(id=>available.find(b=>b.id===id));if(result.some(x=>!x))throw Error('เป้าหมายอยู่นอกระยะ ความสูง หรือสิ่งบัง');return result;}
function atomic(e,fn){const before=copy(e);try{return fn();}catch(err){for(const k of Object.keys(e))delete e[k];Object.assign(e,before);throw err;}}
function use(e,fn,{move=false,noise=true}={}){init(e);return atomic(e,()=>{const p=C.hero(e);if(e.status!=='active'||p.action<1)throw Error('ต้องมีอย่างน้อย 1 AP');if(p.casting&&!move)throw Error('กำลังร่ายเวท ต้องปล่อยหรือยกเลิกก่อน');const ap=p.action;p.moving=move;const out=fn(p);p.action=ap-1;p.moving=false;perceive(e,noise?p:null);return out;});}
C.create=function(...args){const e=old.create(...args);init(e);e.profiles=copy(args[1]?.character?.tacticalProfiles||{});const hero=e.units[0],sense=args[1]?.character?.senses;if(sense){hero.sightRange=sense.sight;hero.hearingRange=sense.hearing;}return e;};
C.validate=function(input){if(input.systems!==2)return old.validate(input);const safe=copy(input);for(const u of safe.units){if(!Number.isInteger(u.action)||u.action<0||u.action>2||!Number.isInteger(u.altitude)||u.altitude<0||u.altitude>2)throw Error('AP/ระดับบินไม่ถูกต้อง');if(!Number.isInteger(u.sightRange)||u.sightRange<1||u.sightRange>20||!Number.isInteger(u.hearingRange)||u.hearingRange<1||u.hearingRange>10||typeof u.moving!=='boolean'||!Array.isArray(u.detected)||u.detected.some(id=>!safe.units.some(t=>t.id===id)))throw Error('ประสาทสัมผัสไม่ถูกต้อง');u.action=Math.min(1,u.action);if(u.casting&&(!N.skills[u.casting.id]?.magic||!Number.isInteger(u.casting.progress)||u.casting.progress<1||u.casting.progress>=u.casting.required||!Number.isInteger(u.casting.required)||u.casting.required>20||u.casting.required<2))throw Error('ข้อมูลร่ายเวทไม่ถูกต้อง');}old.validate(safe);if(!Number.isInteger(input.detectSeed)||input.detectSeed<0||input.detectSeed>4294967295||!input.detectChecks||!Array.isArray(input.discovered)||input.discovered.some(i=>!Number.isInteger(i)||!input.scene.cells[i]))throw Error('ข้อมูลตรวจจับไม่ถูกต้อง');for(const p of Object.values(input.profiles||{}))checkProfile(p);return copy(input);};
C.sees=(e,a,b)=>e.systems===2?inSight(e,a,b,a.moving):old.sees(e,a,b);
C.visible=(e,u)=>e.systems!==2?old.visible(e,u):u.side==='player'||live(e).some(p=>p.side==='player'&&(p.far===e.round||(p.detected||[]).includes(u.id)&&inSight(e,p,u)));
C.observe=e=>e.systems===2?perceive(e):old.observe(e);
C.canHit=(e,a,b,range=a.range)=>e.systems!==2?old.canHit(e,a,b,range):reachable(e,a,b,e.currentTargeting||(a.main&&range===a.range?profile(e,'weapon:'+(a.catalogWeapon?.id||a.main),(a.catalogWeapon||N.weapons[a.main]).targeting||N.weapons[a.main].targeting):{min:1,max:range,heights:[-2,-1,0,1,2],side:'enemy'}));
C.move=(e,n)=>use(e,p=>{if(p.effects?.wall>0)throw Error('กำลังตั้งกำแพงโล่ เคลื่อนที่ไม่ได้');const pool=p.move;p.move=pool||6;const route=old.move(e,n);p.move=pool||6;return route;},{move:true});
C.attack=(e,ids)=>use(e,p=>{const rule=profile(e,'weapon:'+(p.catalogWeapon?.id||p.main),p.catalogWeapon?.targeting||N.weapons[p.main]?.targeting||{min:1,max:p.range,mode:'single',count:1,heights:[-1,0,1],side:'enemy'}),list=targets(e,p,ids,rule);if(!list.length)throw Error('ไม่มีเป้าหมาย');e.currentTargeting=rule;for(const t of list){p.action=1;old.attack(e,t.id);if(e.status!=='active')break;}delete e.currentTargeting;});
for(const name of ['guard','potion','interact','unique','racial'])C[name]=(e,...args)=>use(e,()=>old[name](e,...args));
C.cancelCast=e=>{const p=C.hero(e);if(!p.casting)throw Error('ไม่มีเวทค้าง');delete p.casting;note(e,'ยกเลิกการร่าย • ไม่คืน MP');};
C.cast=function(e,id,ids,selected){init(e);return atomic(e,()=>{const p=C.hero(e),a=N.skills[id];if(!a||!p.skills.includes(id)||p.action<1||e.status!=='active')throw Error('ไม่มี AP หรือยังไม่ได้เรียนสกิล');if(p.casting&&p.casting.id!==id)throw Error('มีเวทค้างอยู่ ต้องปล่อยหรือยกเลิกก่อน');if(!a.magic)return use(e,p=>{const rule=profile(e,'skill:'+id,a.targeting),special=['step','trap','smoke','cry','wall'].includes(id),list=special?[Array.isArray(ids)?ids[0]:ids]:targets(e,p,ids,rule).map(t=>t.id);if(!list.length)throw Error('ไม่มีเป้าหมาย');const mp=p.mana,ap=p.action;for(let k=0;k<list.length;k++){p.action=1;if(k){p.mana=mp;p.cooldowns[id]=e.round;}e.currentTargeting=rule;old.cast(e,id,list[k],selected);delete e.currentTargeting;}p.action=ap;});
if(p.effects.stun){delete p.casting;throw Error('ติดสตัน');}if(p.effects.silence)throw Error('ติดใบ้ ใช้เวทไม่ได้');const required=p.unique==='silent'?1:(e.profiles['skill:'+id]?.castPoints||a.castPoints||1),cost=p.job==='mage'&&a.power>0?Math.max(3,a.cost-1):a.cost;
if(!p.casting){if((p.cooldowns[id]||0)>e.round||p.mana<cost)throw Error('เวทยังไม่พร้อมหรือ MP ไม่พอ');}
if(required>1&&(!p.casting||p.casting.progress+1<required)){if(!p.casting){p.mana-=cost;p.casting={id,progress:0,required,cost};}p.casting.progress++;p.action--;note(e,a.name+' ร่าย '+p.casting.progress+'/'+required+' • ใช้ 1 AP');perceive(e,p);return;}
const held=p.casting,ap=p.action,rule=profile(e,'skill:'+id,a.targeting),self=['cry','wall'].includes(id),tile=['step','trap','smoke','quagmire'].includes(id),ally=['heal','cure','barrier','aid','antidote','protect'].includes(id);let list=self||tile||ally&&rule.mode==='single'?[Array.isArray(ids)?ids[0]:ids]:targets(e,p,ids,rule).map(u=>u.id);if(!list.length)throw Error('ไม่มีเป้าหมาย');delete p.casting;
for(let k=0;k<list.length;k++){p.action=1;if(held||k>0)p.mana+=cost;p.cooldowns[id]=e.round;e.currentTargeting=rule;old.cast(e,id,list[k],selected);delete e.currentTargeting;}p.action=ap-1;perceive(e,p);});};
C.spell=(e,id)=>e.design===1&&!e.chapter?C.cast(e,C.hero(e).skills.find(k=>N.skills[k].magic&&N.skills[k].power>0),id):use(e,()=>old.spell(e,id));
C.endTurn=function(e){init(e);return atomic(e,()=>{for(const u of e.units){u.moving=false;u.detected=[];delete u.suspicion;}e.detectChecks={};e.detectPhase='enemy';old.endTurn(e);e.detectPhase='player';if(e.status==='active')for(const p of live(e).filter(u=>u.side==='player')){p.action=2;p.moving=false;if(!['dragon','wind'].includes(p.form?.type))p.altitude=0;}perceive(e);});};
C.fly=(e,h)=>use(e,p=>{if(!Number.isInteger(h)||h<0||h>2)throw Error('ระดับบิน 0–2');if(h&&p.form?.type!=='dragon'&&p.form?.type!=='wind')throw Error('ต้องมีร่างมังกรหรือร่างลมจึงบินได้');p.altitude=h;},{move:true});
C.setProfile=function(e,key,p){checkProfile(p);if(p.castPoints!==undefined&&(!Number.isInteger(p.castPoints)||p.castPoints<1||p.castPoints>20))throw Error('แต้มร่าย 1–20');e.profiles[key]=copy(p);};
C.tactical={init,fog,level,profile,targets,inSight,perceive,chance,damageAllowed(e,a,b){const r=e.currentTargeting;if(!r)return true;const d=old.distance(e.scene,a.n,b.n);return d>=r.min&&d<=r.max&&r.heights.includes(level(e,b)-level(e,a))&&(r.side==='both'||(r.side==='ally')===(a.side===b.side));}};
if(typeof module!=='undefined')module.exports=C;
})(typeof window==='undefined'?globalThis:window);
